API_name: get_salary_estimation
Description:
{
  "description": "Retrieves detailed salary estimation data, including minimum, maximum, and median base/total salary, for a specified job title and location, with optional filtering by location type and years of experience.",
  "required_parameters": [
    {
      "name": "job_title",
      "type": "String",
      "description": "The job title for which to get salary estimation (e.g., 'nodejs developer')."
    },
    {
      "name": "location",
      "type": "String",
      "description": "The free-text location/area in which to get salary estimation (e.g., 'new york')."
    }
  ],
  "optional_parameters": [
    {
      "name": "location_type",
      "type": "Enum",
      "description": "Specify the type of the location for additional accuracy. Allowed values: ANY, CITY, STATE, COUNTRY.",
      "default": "ANY"
    },
    {
      "name": "years_of_experience",
      "type": "Enum",
      "description": "Get job estimation for a specific experience level range (years). Allowed values: ALL, LESS_THAN_ONE, ONE_TO_THREE, FOUR_TO_SIX, SEVEN_TO_NINE, TEN_TO_FOURTEEN, ABOVE_FIFTEEN.",
      "default": "ALL"
    },
    {
      "name": "fields",
      "type": "String",
      "description": "A comma separated list of job salary fields to include in the response (field projection). By default all fields are returned. Example: 'job_title,median_salary,location'."
    }
  ]
}

