  "description": "Provides a way to search the arXiv repository for scientific papers using a variety of filters and search parameters.",
  "required_parameters": [
    {
      "name": "search_term",
      "type": "String",
      "description": "Search term to query arXiv."
    }
  ],
  "optional_parameters": [
    {
      "name": "date_from",
      "type": "String",
      "description": "The start date for filtering papers by submission date in 'YYYY-MM-DD' format."
    },
    {
      "name": "start",
      "type": "Number",
      "description": "The starting index for pagination. Default is 0 (first page).",
      "default": "0",
      "minimum": "0"
    },
    {
      "name": "date_type",
      "type": "String",
      "description": "The type of date to filter papers by.",
      "default": "Submission Date"
    },
    {
      "name": "field",
      "type": "String",
      "description": "The field to search in. Options are 'Title', 'Authors', 'Comments', or 'All fields'.",
      "default": "All fields"
    },
    {
      "name": "date_to",
      "type": "String",
      "description": "The end date for filtering papers by submission date in 'YYYY-MM-DD' format."
    },
    {
      "name": "num_results",
      "type": "Number",
      "description": "The maximum number of results to return.",
      "default": "5",
      "minimum": "1"
    }
  ]
}

